-- LevelUp Ecosystem (levelup-ecosystem.com, ws_6e797257f5b32b86) site content, moved out of the
-- hard-coded arrays of the app.levelup-ecosystem repository into the tenant tables:
--   components/blocks/pricing.tsx (buildPlans, carePlans)  -> services
--   components/blocks/pricing-table.tsx (comparison matrix)  -> content_blocks pricing/comparison
--   components/blocks/faq.tsx (categories)                    -> faq_items
--   components/blocks/testimonials.tsx (items, de-duplicated) -> reviews
--   data/projects.ts + app/projects/page.tsx (concepts)       -> content_blocks projects/list, projects/concepts
--   config/identity.ts + app/layout.tsx metadata              -> website_settings contact/social/branding/seo
-- The site reads all of it through public.get_site_bundle() and keeps the
-- hard-coded arrays only as a fallback.
--
-- Supersedes the legacy public.pricing_plans table and the French fallback plans
-- in lib/supabase.ts (getPricingPlans), which the site no longer reads. The
-- legacy projects/faqs/testimonials/entities/site_settings readers are removed too.
--
-- Idempotent: ON CONFLICT DO NOTHING / WHERE NOT EXISTS, nothing is deleted or
-- overwritten, so edits made later in the dashboard are kept on re-run.

-- ============================================================================
-- Features needed to publish services (pricing) and reviews (testimonials)
-- ============================================================================

INSERT INTO public.website_features (website_id, organization_id, feature_key)
SELECT 'ws_6e797257f5b32b86', w.organization_id, v.feature_key
FROM (VALUES ('services'), ('reviews')) AS v(feature_key)
JOIN public.websites w ON w.id = 'ws_6e797257f5b32b86' AND w.organization_id = '716c151f-1c1f-4ba6-a02c-53ab6a9aa169'
ON CONFLICT (website_id, feature_key) DO NOTHING;

-- ============================================================================
-- Pricing: 4 website build plans + 3 monthly care plans
-- price_label = the price exactly as displayed; the period, notes, CTA and the
-- expanded checklist (full_features) live in data.
-- ============================================================================

