VALUES ('ws_6e797257f5b32b86', '716c151f-1c1f-4ba6-a02c-53ab6a9aa169', 'starter', 'Starter', 'website_plan', 'A bespoke high-converting showcase website built from scratch. Includes mobile-first responsive architecture, Google Maps integration, technical and local SEO foundations, and 100% full ownership with zero monthly fees.', 85000, '$850', 'USD', NULL, false, ARRAY['Custom bespoke design (up to 5 pages)', 'Mobile, tablet & desktop responsive', 'Google Maps & Local SEO foundation', 'Contact & lead capture form', '100% website code ownership']::text[], $j${"subtitle":"For small businesses needing a clean, professional web presence","price_period":"/one-time","secondary_note":null,"cta_text":"Get Started with Starter ($850)","cta_href":"/contact?plan=starter","full_features":[{"category":"Included Deliverables","items":[{"text":"Custom website design (no generic templates)","included":true},{"text":"Up to 5 custom-crafted pages","included":true},{"text":"Responsive design: mobile, tablet & desktop","included":true},{"text":"Contact and lead capture form","included":true},{"text":"Google Maps integration with interactive directions","included":true},{"text":"Basic technical SEO architecture","included":true},{"text":"Local SEO foundation targeting your service area","included":true},{"text":"Optimized meta titles & descriptions","included":true},{"text":"Image & asset optimization (sub-2s loading speed target)","included":true},{"text":"SSL / HTTPS security encryption standard","included":true},{"text":"Google Analytics setup","included":true},{"text":"Basic accessibility (WCAG compliant)","included":true},{"text":"2 rounds of revisions included","included":true},{"text":"Website launch & verification","included":true},{"text":"100% full website and code ownership","included":true}]},{"category":"Features Not Included (Available in Secure)","items":[{"text":"24/7 online booking engine","included":false},{"text":"Live 2-way calendar sync (Google, Apple, Square)","included":false},{"text":"Automated SMS/Email appointment confirmations","included":false},{"text":"Database security audit & access hardening","included":false},{"text":"Included monthly website updates (Care optional)","included":false}]}]}$j$::jsonb, 0, 'published')
ON CONFLICT (website_id, slug) DO NOTHING;

