VALUES ('ws_6e797257f5b32b86', '716c151f-1c1f-4ba6-a02c-53ab6a9aa169', 'secure', 'Secure', 'website_plan', 'An automated appointment booking and customer acquisition powerhouse. Includes self-service scheduling, 2-way calendar sync, cybersecurity hardening, and advanced local SEO.', 150000, '$1,500', 'USD', 'Business Engine', false, ARRAY['24/7 Online Booking System', 'Live 2-Way Calendar Sync', 'Cybersecurity Hardening & Audit', 'Google Business Profile Setup', 'Advanced Local & Technical SEO']::text[], $j${"subtitle":"A complete business engine — not just a pretty website","price_period":"/one-time","secondary_note":null,"cta_text":"Get Started with Secure ($1,500)","cta_href":"/contact?plan=secure","full_features":[{"category":"Business & Booking System","items":[{"text":"Everything in Starter included","included":true},{"text":"Online booking system for customer self-scheduling","included":true},{"text":"Live 2-way calendar integration (Google, Apple, Square, Calendly)","included":true},{"text":"Automated appointment email confirmations to reduce no-shows","included":true},{"text":"Lead capture & notification pipeline","included":true},{"text":"Instant email notifications for new bookings","included":true},{"text":"Google Business Profile setup & integration assistance","included":true},{"text":"Advanced interactive contact/lead intake forms","included":true}]},{"category":"Search Visibility & Security","items":[{"text":"Advanced on-page SEO targeting high-intent buyer searches","included":true},{"text":"Search-friendly site architecture","included":true},{"text":"Local SEO optimization with geo-coordinates","included":true},{"text":"Structured data & Schema.org markup","included":true},{"text":"Google Search Console setup & sitemap submission","included":true},{"text":"SSL / HTTPS encryption with security headers","included":true},{"text":"Anti-spam protection & honeypot filtering","included":true},{"text":"Admin authentication hardening & access review","included":true},{"text":"Database security rules where applicable","included":true},{"text":"Mobile speed optimization & Core Web Vitals tuning","included":true},{"text":"3 rounds of revisions included","included":true}]},{"category":"Features Not Included (Available in Bundle / Care)","items":[{"text":"Managed cloud hosting & CDN (Care optional)","included":false},{"text":"Automated daily offsite backups (Care optional)","included":false},{"text":"Monthly on-demand website edits (Care optional)","included":false}]}]}$j$::jsonb, 10, 'published')
