VALUES ('ws_6e797257f5b32b86', '716c151f-1c1f-4ba6-a02c-53ab6a9aa169', 'secure-care', 'Secure + Care Bundle', 'website_plan', 'The complete turnkey package: you get the $1,500 Secure website build plus a full year of managed cloud hosting, daily backups, continuous security defense, and monthly updates handled for you.', 230000, '$2,300', 'USD', 'Turnkey Bundle', false, ARRAY['Full Secure Build Included ($1,500 value)', '1 Full Year of Managed Cloud Hosting', 'Daily Automated Offsite Backups', '24/7 Continuous Uptime Monitoring', 'Monthly website updates (up to 2h/mo)']::text[], $j${"subtitle":"Complete build + 1 year of managed hosting, backups & updates","price_period":"/turnkey package","secondary_note":"Full Secure build + 1 year of Pro Care ($99/mo value)","cta_text":"Choose Secure + Care ($2,300)","cta_href":"/contact?plan=secure-care","full_features":[{"category":"Complete Website Build","items":[{"text":"Everything included in the $1,500 Secure build","included":true},{"text":"24/7 online booking engine & live calendar sync","included":true},{"text":"Full cybersecurity audit and hardening","included":true},{"text":"Advanced local SEO & Google Business Profile setup","included":true},{"text":"3 rounds of build revisions included","included":true}]},{"category":"Included 1-Year Care Management","items":[{"text":"Managed ultra-fast cloud hosting on edge infrastructure","included":true},{"text":"Global Content Delivery Network (CDN)","included":true},{"text":"Automated daily offsite backups with instant recovery","included":true},{"text":"24/7 continuous uptime monitoring & health checks","included":true},{"text":"Up to 2 hours of monthly website updates (text, photos, prices)","included":true},{"text":"Continuous SSL renewal & DNS management","included":true},{"text":"Priority developer support","included":true}]}]}$j$::jsonb, 20, 'published')
