-- ============================================================================
-- FAQ (components/blocks/faq.tsx): 3 categories
-- ============================================================================

INSERT INTO public.faq_items (website_id, organization_id, category, question, answer, sort_order, status)
SELECT 'ws_6e797257f5b32b86', '716c151f-1c1f-4ba6-a02c-53ab6a9aa169', v.category, v.question, v.answer, v.sort_order, 'published'
FROM (VALUES
  ('About LevelUp Ecosystem', 'What is LevelUp Ecosystem?', 'LevelUp Ecosystem is an independent web architecture and development studio based in San Diego, California. The studio builds fast, secure websites with 24/7 online booking, local SEO, and cybersecurity basics for businesses, barbershops, salons, and creators.', 0),
  ('About LevelUp Ecosystem', 'Who is Richelieu Bonte?', 'Richelieu Bonte is the founder and principal engineer of LevelUp Ecosystem, an independent web design studio building secure, AI-assisted websites for local businesses and creators. He is a cybersecurity student based in San Diego, California, originally from the Democratic Republic of Congo.', 10),
  ('About LevelUp Ecosystem', 'What is LevelStudio?', $c$LevelStudio is LevelUp Ecosystem's automated AI preview generator, allowing clients to test website concepts and interactive mobile prototypes on their phone before human engineering and deployment.$c$, 20),
  ('Services & Google Ranking', 'How does the free interactive preview work?', 'You send us your business name, services, and any photos or ideas you have. Within 24 to 48 hours, we build a functional, interactive mobile preview of your site. You get to test it on your phone before spending a single dollar. If you approve, we move forward. If not, you owe nothing.', 100),
  ('Services & Google Ranking', 'Can you help our business rank higher on Google Maps in San Diego?', 'Yes. Local visibility requires coordinated website data and a verified Google Business Profile. We format your name, phone number, and service areas to match your Google listing, insert local business Schema.org structured data, and optimize page load speeds so mobile searchers convert into appointments.', 110),
  ('Services & Google Ranking', 'How long does a website take to build and launch?', 'Once you approve your free preview, full custom development, 24/7 online appointment booking configuration, security hardening, and domain launch typically take 7 to 10 days.', 120),
  ('Security & Pricing', 'What is included in the Website Security Check?', 'We audit your domain registrar and DNS settings, verify SSL HTTPS certificates, audit database permissions, implement two-factor authentication (2FA) on your hosting and business email accounts, install spam bot honeypots, and test for credential leakage.', 200),
  ('Security & Pricing', 'Do I own my website, code, and domain?', 'Yes, 100%. Once final payment is settled, you own all rights to your domain, branding, text, and customer lists. There are no lock-in contracts or hostage fees.', 210),
  ('Security & Pricing', 'What is included in the $49/month Care Plan?', 'High-speed cloud hosting, automated daily backups, monthly security updates, 24/7 uptime monitoring, and on-demand content edits (updating hours, prices, service menus, or staff members).', 220)
) AS v(category, question, answer, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.faq_items WHERE website_id = 'ws_6e797257f5b32b86');

